/**
 * File system abstraction (Node.js version).
 *
 * This file is swapped with fs.browser.ts for browser builds
 * via the package.json browser field.
 */
import * as nodeFs from "node:fs";
import * as nodeFsPromises from "node:fs/promises";
import * as nodePath from "node:path";
import { homedir } from "node:os";
import { randomUUID } from "node:crypto";
export function resolveConfigPath(filePath) {
    const expanded = filePath === "~" || filePath.startsWith("~/") || filePath.startsWith("~\\")
        ? nodePath.join(homedir(), filePath.slice(1))
        : filePath;
    const absolute = nodePath.resolve(expanded);
    return nodeFs.existsSync(absolute) ? nodeFs.realpathSync(absolute) : absolute;
}
export function homeDirectory() {
    return homedir();
}
export const path = nodePath;
// ---------------------------------------------------------------------------
// Async operations (used by trace dump fallback)
// ---------------------------------------------------------------------------
export async function mkdir(dir) {
    await nodeFsPromises.mkdir(dir, { recursive: true });
}
export async function writeFileAtomic(filePath, content) {
    const tempPath = `${filePath}.${randomUUID()}.tmp`;
    const file = await nodeFsPromises.open(tempPath, "wx", 0o600);
    try {
        try {
            await file.writeFile(content, "utf8");
            await file.sync();
        }
        finally {
            await file.close();
        }
        await nodeFsPromises.rename(tempPath, filePath);
    }
    finally {
        await nodeFsPromises.rm(tempPath, { force: true });
    }
}
export async function readdir(dir) {
    return nodeFsPromises.readdir(dir);
}
export async function stat(filePath) {
    return nodeFsPromises.stat(filePath);
}
export async function unlink(filePath) {
    await nodeFsPromises.unlink(filePath);
}
// ---------------------------------------------------------------------------
// Sync operations (used by prompt cache)
// ---------------------------------------------------------------------------
export function existsSync(p) {
    return nodeFs.existsSync(p);
}
export function mkdirSync(dir) {
    nodeFs.mkdirSync(dir, { recursive: true });
}
export function writeFileSync(filePath, content) {
    nodeFs.writeFileSync(filePath, content);
}
export function renameSync(oldPath, newPath) {
    nodeFs.renameSync(oldPath, newPath);
}
export function unlinkSync(filePath) {
    nodeFs.unlinkSync(filePath);
}
export function readFileSync(filePath) {
    return nodeFs.readFileSync(filePath, "utf-8");
}
// ---------------------------------------------------------------------------
// Lock primitives (used by the OAuth refresh directory lock)
// ---------------------------------------------------------------------------
export async function mkdirExclusive(dir) {
    // Non-recursive mkdir throws EEXIST if the directory already exists, which
    // is the atomic test-and-set the cross-process lock relies on.
    await nodeFsPromises.mkdir(dir, { mode: 0o700 });
}
export function statMtimeMs(filePath) {
    try {
        return nodeFs.statSync(filePath).mtimeMs;
    }
    catch {
        return undefined;
    }
}
export async function rmRecursive(filePath) {
    // On Windows, deletes fail with EBUSY/EPERM while another process (e.g. the
    // Python or Go SDK reading an OAuth lock file) has the file open. Node
    // retries those errors with a short linear backoff (~150ms total).
    await nodeFsPromises.rm(filePath, {
        recursive: true,
        force: true,
        maxRetries: 5,
        retryDelay: 10,
    });
}
